import { render } from '@solidjs/web';
import { createMemo, action, affects, refresh, isPending, Loading } from 'solid-js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A pretend server: it keeps the like count and takes 600ms to save.
const api = {
  likes: 41,
  async read() {
    await sleep(100);
    return api.likes;
  },
  async like(fail) {
    await sleep(600);
    if (fail) throw new Error('Could not save your like.');
    api.likes += 1;
  },
};

function LikeButton() {
  const likes = createMemo(() => api.read());

  const like = async () => {
    await api.like();
  };

  return (
    <Loading fallback={<p>Loading...</p>}>
      <button onClick={() => like()}>
        {isPending(likes) ? 'Saving...' : `Like (${likes()})`}
      </button>
    </Loading>
  );
}

render(() => <LikeButton />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createMemo, action, affects, refresh, isPending, Loading } from 'solid-js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A pretend server: it keeps the like count and takes 600ms to save.
const api = {
  likes: 41,
  async read() {
    await sleep(100);
    return api.likes;
  },
  async like(fail) {
    await sleep(600);
    if (fail) throw new Error('Could not save your like.');
    api.likes += 1;
  },
};

function LikeButton() {
  const likes = createMemo(() => api.read());

  const like = action(function* () {
    affects(likes);
    yield api.like();
    refresh(likes);
  });

  return (
    <Loading fallback={<p>Loading...</p>}>
      <button onClick={() => like()}>
        {isPending(likes) ? 'Saving...' : `Like (${likes()})`}
      </button>
    </Loading>
  );
}

render(() => <LikeButton />, document.getElementById('app'));
